import type { DesignContent } from "@/lib/design-content";

export const content: DesignContent = {"slug": "rental-dispute", "title": "UniShare · Rental dispute", "css": "\n:root{\n  --ink:#14201e; --muted:#5b6866; --teal:#0b5b57; --teal-soft:#e3efed;\n  --line:#14201e; --hair:#dfe4e3; --panel:#f4f6f5; --amber-bg:#fdf1d3; --amber-tx:#7a4d00;\n  --red-bg:#fbe3e1; --red-tx:#a02a22; --white:#fff;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"Schibsted Grotesk\",system-ui,-apple-system,\"Segoe UI\",sans-serif;color:var(--ink);background:var(--white);font-size:14px;line-height:1.45}\na{color:inherit;text-decoration:none}\nbutton{font:inherit;cursor:pointer}\n:focus-visible{outline:2px solid var(--teal);outline-offset:2px}\n\n/* nav */\n.nav{border-bottom:2px solid var(--line);height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 48px;gap:24px}\n.brand{display:flex;align-items:center;gap:10px;font-weight:700;font-size:20px;color:var(--ink)}\n.brand svg{width:24px;height:24px;color:var(--teal)}\n.nav ul{list-style:none;display:flex;gap:22px;font-size:13px}\n.nav ul a{padding:19px 0;display:block;border-bottom:2px solid transparent;margin-bottom:-2px}\n.nav ul a.on{color:var(--teal);font-weight:600;border-color:var(--teal)}\n.nav-r{display:flex;align-items:center;gap:18px;font-size:13px}\n.sos{display:flex;align-items:center;gap:5px;font-weight:600;color:var(--teal)}\n.user{display:flex;align-items:center;gap:8px}\n.avatar{width:28px;height:28px;border-radius:50%;background:var(--teal-soft);border:1px solid var(--teal);color:var(--teal);font-size:10px;display:grid;place-items:center;font-weight:600}\n.user small{display:block;color:var(--muted);font-size:10px;line-height:1.2}\n.user b{font-weight:600;font-size:12px;line-height:1.2;display:block}\n.nav svg.i{width:15px;height:15px}\n\n/* layout */\nmain{max-width:772px;margin:0 auto;padding:0 0 56px}\n.wrap{max-width:772px;margin:0 auto}\n.crumbs{font-size:11px;color:var(--muted);margin:19px 0 22px;display:flex;gap:8px}\n.crumbs a:last-child{color:var(--teal)}\n.eyebrow{font-size:9.5px;letter-spacing:.04em;color:var(--teal);font-weight:600;text-transform:uppercase;margin-bottom:10px}\nh1{font-size:30px;line-height:1.15;font-weight:800;letter-spacing:-.01em;margin-bottom:8px}\n.lede{color:var(--muted);font-size:13px;margin-bottom:22px}\n.banner{background:var(--amber-bg);border-radius:8px;padding:14px 20px;display:flex;gap:12px;margin-bottom:22px}\n.banner svg{width:16px;height:16px;color:var(--teal);flex:none;margin-top:2px}\n.banner b{display:block;color:var(--teal);font-size:13px;margin-bottom:1px}\n.banner span{font-size:11px;color:var(--muted)}\n\n.grid{display:grid;grid-template-columns:1fr 293px;gap:20px;align-items:start}\n.col{display:flex;flex-direction:column;gap:20px;min-width:0}\n.card{border:1.5px solid var(--line);border-radius:12px;padding:16px 16px 18px;background:var(--white)}\n.card.panel{background:var(--panel)}\n.card h2{font-size:17px;font-weight:700;margin:2px 0 14px;line-height:1.25}\n\n/* product */\n.prod{display:flex;gap:14px;padding:16px}\n.thumb{width:102px;height:80px;border-radius:8px;flex:none;object-fit:cover;object-position:center 35%;display:block;background:#a8362f}\n.prod small{color:var(--muted);font-size:10.5px}\n.prod h3{font-size:19px;font-weight:700;line-height:1.2;margin:3px 0 5px}\n.prod p{color:var(--muted);font-size:12px;margin-bottom:8px}\n.pill{display:inline-block;font-size:10px;font-weight:600;padding:2px 9px;border-radius:999px}\n.pill.red{background:var(--red-bg);color:var(--red-tx)}\n.pill.amber{background:var(--amber-bg);color:var(--amber-tx)}\n\n/* report */\n.lbl{font-weight:700;font-size:13px;margin-bottom:8px}\n.select{display:inline-flex;align-items:center;gap:30px;border:1px solid var(--hair);border-radius:8px;padding:9px 12px;font-size:12px;margin-bottom:18px;background:var(--white)}\n.select svg{width:12px;height:12px}\n.textbox{border:1px solid var(--hair);border-radius:8px;padding:14px;font-size:12.5px;line-height:1.65;color:#3a4745;margin-bottom:14px}\n.row{display:flex;justify-content:space-between;gap:14px;font-size:12px;color:var(--muted);padding:2px 0}\n.row b{color:var(--ink);font-weight:500;text-align:right}\n.sub{font-size:10.5px;color:var(--muted);margin-top:10px}\n\n/* evidence */\n.ev{display:flex;gap:14px;margin-bottom:16px}\n.ev .left{width:130px;flex:none}\n.ev .left .thumb{width:130px;height:83px}\n.ev .left small{display:block;font-size:9.5px;color:var(--muted);margin-top:4px;line-height:1.3}\n.files{flex:1;display:flex;flex-direction:column;gap:8px}\n.file{background:var(--panel);border-radius:8px;padding:10px 12px;display:flex;align-items:center;gap:10px;font-size:11px}\n.file svg{width:14px;height:14px;color:var(--teal);flex:none}\n.drop{border:1.5px dashed var(--teal);border-radius:8px;padding:20px 12px;text-align:center;margin-bottom:12px;cursor:pointer;transition:background .15s}\n.drop:hover,.drop.over{background:var(--teal-soft)}\n.drop svg{width:20px;height:20px;color:var(--teal);margin-bottom:6px}\n.drop b{display:block;color:var(--teal);font-size:11.5px;margin-bottom:6px}\n.drop small{color:var(--muted);font-size:10px}\n.btn{border:1.5px solid var(--teal);color:var(--teal);background:var(--white);border-radius:8px;padding:9px 16px;font-weight:600;font-size:12px}\n.btn:hover{background:var(--teal-soft)}\n.note{font-size:10px;color:var(--muted);margin-top:12px}\n#added{list-style:none;display:flex;flex-direction:column;gap:8px;margin-bottom:12px}\n\n/* case */\n.case h2{font-size:20px;margin-bottom:12px}\n.steps{list-style:none;margin:16px 0 14px;display:flex;flex-direction:column;gap:14px}\n.steps li{display:flex;gap:10px}\n.dot{width:22px;height:22px;border-radius:50%;background:var(--teal-soft);color:var(--teal);display:grid;place-items:center;flex:none}\n.dot svg{width:12px;height:12px}\n.steps b{display:block;font-size:12.5px;font-weight:700}\n.steps span{display:block;font-size:11px;color:var(--muted);line-height:1.4}\n.fine{font-size:10.5px;color:var(--muted);border-top:1px solid var(--hair);padding-top:12px}\n.tok .row{padding:5px 0;font-size:12px}\n.tok .row b.hold{color:var(--teal);font-weight:700}\n.tok .fine{border:0;padding-top:8px}\n\nfooter{border-top:2px solid var(--line);padding:22px 48px 26px;display:flex;justify-content:space-between;font-size:11.5px;color:var(--muted)}\nfooter nav{display:flex;gap:22px}\nfooter nav a{color:var(--teal);font-weight:600}\n@media (max-width:1040px){.nav ul{display:none}}\n@media (max-width:860px){\n  .grid{grid-template-columns:1fr}\n  main{padding:0 20px 40px}\n  .nav,footer{padding-left:20px;padding-right:20px}\n  .ev{flex-direction:column}\n  .ev .left{width:100%}\n  footer{flex-direction:column;gap:10px}\n}\n", "body": "\n\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <defs>\n    <symbol id=\"clock\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></symbol>\n    <symbol id=\"check\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></symbol>\n    <symbol id=\"file\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M6 3h8l4 4v14H6z\"/><path d=\"M14 3v4h4M9 14l2 2 4-4\" stroke-linecap=\"round\"/></symbol>\n  </defs>\n</svg>\n\n<header class=\"nav\">\n  <a class=\"brand\" href=\"/\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\"><circle cx=\"7\" cy=\"12\" r=\"4\"/><circle cx=\"17\" cy=\"12\" r=\"4\"/></svg>\n    UniShare\n  </a>\n  <ul>\n    <li><a href=\"/campus-home\">Home</a></li>\n    <li><a href=\"/marketplace\">Marketplace</a></li>\n    <li><a href=\"/my-products\">My products</a></li>\n    <li><a class=\"on\" href=\"/my-rentals\">My rentals</a></li>\n    <li><a href=\"/ride-home-and-search\">Rides</a></li>\n    <li><a href=\"/wallet-overview\">Wallet</a></li>\n    <li><a href=\"/favorites\">Favorites</a></li>\n  </ul>\n  <div class=\"nav-r\">\n    <svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M6 17V11a6 6 0 0 1 12 0v6l1.5 2h-15zM10 21h4\"/></svg>\n    <a class=\"sos\" href=\"/student-sos-assistance\"><svg class=\"i\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"><path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/><path d=\"M9 12l2 2 4-4\" stroke-linecap=\"round\"/></svg>SOS</a>\n    <div class=\"user\">\n      <span class=\"avatar\">FR</span>\n      <div><b>Farhana Rahman</b><small>My profile</small></div>\n    </div>\n  </div>\n</header>\n\n<main>\n  <nav class=\"crumbs\" aria-label=\"Breadcrumb\"><a href=\"/campus-home\">Home</a><span>›</span><a href=\"/my-rentals\">My rentals</a></nav>\n\n  <div class=\"eyebrow\">University of Dhaka · Verified students only</div>\n  <h1>Let’s get this sorted, fairly.</h1>\n  <p class=\"lede\">Your report has been submitted. Keep the rental details and evidence together here.</p>\n\n  <div class=\"banner\" role=\"status\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v5M12 8v.01\"/></svg>\n    <div>\n      <b>Submitted · Campus support is reviewing your report</b>\n      <span>Case US-D203 · Submitted 13 October, 9:20 AM. The 150-token deposit remains held while the issue is reviewed.</span>\n    </div>\n  </div>\n\n  <div class=\"grid\">\n    <!-- left column -->\n    <div class=\"col\">\n      <section class=\"card prod\">\n        <img class=\"thumb\" src=\"data:image/jpeg;base64,\" alt=\"AirPods with charging case\">\n        <div>\n          <small>US-R1034 · AirPods</small>\n          <h3>AirPods with charging case</h3>\n          <p>80 tokens / day · Rafiul Karim</p>\n          <span class=\"pill red\">Disputed</span>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <h2>Your submitted report</h2>\n        <div class=\"lbl\">Reason for dispute</div>\n        <div class=\"select\">Item not working as described\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg>\n        </div>\n        <div class=\"lbl\">What happened?</div>\n        <div class=\"textbox\">The right AirPod stopped charging during my rental on 11 October. I messaged Rafiul that evening and returned the case and both earbuds on 12 October at 2 PM. I’m asking for the condition to be reviewed before the deposit is released or any deduction is considered.</div>\n        <div class=\"row\"><span>Requested resolution</span><b>Review item condition and release deposit</b></div>\n        <div class=\"sub\">Submitted by Farhana Rahman · 13 Oct 2026, 9:20 AM</div>\n      </section>\n\n      <section class=\"card\">\n        <h2>Evidence · 3 files attached</h2>\n        <div class=\"ev\">\n          <div class=\"left\">\n            <img class=\"thumb\" src=\"data:image/jpeg;base64,\" alt=\"earbuds-at-return.jpg\">\n            <small>earbuds-at-return.jpg 1.8 MB · Attached</small>\n          </div>\n          <div class=\"files\">\n            <div class=\"file\"><svg><use href=\"#file\"/></svg>charging-check.mp4 · 8.2 MB</div>\n            <div class=\"file\"><svg><use href=\"#file\"/></svg>owner-messages.pdf · 640 KB</div>\n          </div>\n        </div>\n        <ul id=\"added\"></ul>\n        <div class=\"drop\" id=\"drop\" tabindex=\"0\" role=\"button\" aria-label=\"Drop additional evidence here or browse files\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 18a4.5 4.5 0 0 1-.5-9A6 6 0 0 1 18 9.5 4 4 0 0 1 17.5 18\"/><path d=\"M12 12v8M9 14.5l3-3 3 3\"/></svg>\n          <b>Drop additional evidence here or browse files</b>\n          <small>JPG, PNG, PDF or MP4 · Up to 10 MB per file</small>\n        </div>\n        <input id=\"picker\" type=\"file\" hidden multiple accept=\".jpg,.jpeg,.png,.pdf,.mp4\">\n        <button class=\"btn\" id=\"add\" type=\"button\">Add evidence</button>\n        <p class=\"note\">Additional files are added to this case. Share only relevant evidence; avoid exposing other students’ personal details.</p>\n      </section>\n    </div>\n\n    <!-- right column -->\n    <aside class=\"col\">\n      <section class=\"card case\">\n        <h2>Case US-D203</h2>\n        <span class=\"pill amber\">Under review</span>\n        <ol class=\"steps\">\n          <li><span class=\"dot\"><svg><use href=\"#check\"/></svg></span><div><b>Report submitted</b><span>13 Oct · 9:20 AM · Your reason and files were received.</span></div></li>\n          <li><span class=\"dot\"><svg><use href=\"#clock\"/></svg></span><div><b>Evidence review</b><span>Campus support is reviewing both students’ records.</span></div></li>\n          <li><span class=\"dot\"><svg><use href=\"#clock\"/></svg></span><div><b>Decision and token update</b><span>You’ll be notified here when a decision is recorded.</span></div></li>\n        </ol>\n        <p class=\"fine\">No decision has been made. You do not need to send another dispute for this rental.</p>\n      </section>\n\n      <section class=\"card tok\">\n        <h2>Tokens during review</h2>\n        <div class=\"row\"><span>Rental fee paid · 1 day</span><b>80 tokens</b></div>\n        <div class=\"row\"><span>Refundable deposit</span><b class=\"hold\">150 tokens held</b></div>\n        <div class=\"row\"><span>Deposit released so far</span><b>0 tokens</b></div>\n        <p class=\"fine\">The hold remains in place. No deposit deduction, fee adjustment or refund has been decided.</p>\n      </section>\n\n      <section class=\"card panel\">\n        <h2>Rental context</h2>\n        <div class=\"row\"><span>Rental dates</span><b>11–12 Oct 2026</b></div>\n        <div class=\"row\"><span>Return handover</span><b>Arts Building · 12 Oct, 2 PM</b></div>\n        <p class=\"sub\" style=\"margin:10px 0 16px\">Owner: Rafiul Karim · Verified DU student. Final closure is paused while the case is reviewed.</p>\n        <button class=\"btn\" type=\"button\">Contact support</button>\n      </section>\n    </aside>\n  </div>\n</main>\n\n<footer>\n  <span>UniShare. Made for university students in Bangladesh.</span>\n  <nav><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/get-help\">Get help</a><a href=\"/\">Log out</a></nav>\n</footer>\n\n\n", "scripts": ["\n(function(){\n  var drop=document.getElementById('drop'),picker=document.getElementById('picker'),list=document.getElementById('added');\n  function open(){picker.click()}\n  document.getElementById('add').addEventListener('click',open);\n  drop.addEventListener('click',open);\n  drop.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}});\n  ['dragenter','dragover'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.add('over')})});\n  ['dragleave','drop'].forEach(function(t){drop.addEventListener(t,function(e){e.preventDefault();drop.classList.remove('over')})});\n  drop.addEventListener('drop',function(e){show(e.dataTransfer.files)});\n  picker.addEventListener('change',function(){show(picker.files)});\n  function show(files){\n    Array.prototype.forEach.call(files,function(f){\n      var li=document.createElement('li');li.className='file';\n      var mb=(f.size/1048576).toFixed(1);\n      li.innerHTML='<svg><use href=\"#file\"/></svg>';\n      li.appendChild(document.createTextNode(f.name+' · '+(f.size>1048576?mb+' MB':Math.max(1,Math.round(f.size/1024))+' KB')+(f.size>10485760?' · Too large (max 10 MB)':'')));\n      list.appendChild(li);\n    });\n  }\n})();\n"], "fonts": ["https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;600;700;800&display=swap"]};

export default content;
